void PageHandlerAsyncWaiter::GetUrls(
    ChromeUrlsDataPtr* out_urls_data) {
  base::RunLoop loop;
  proxy_->GetUrls(
      base::BindOnce(
          [](base::RunLoop* loop,
             ChromeUrlsDataPtr* out_urls_data
,
             ChromeUrlsDataPtr urls_data) {*out_urls_data = std::move(urls_data);
            loop->Quit();
          },
          &loop,
          out_urls_data));
  loop.Run();
}

ChromeUrlsDataPtr PageHandlerAsyncWaiter::GetUrls(
    ) {
  ChromeUrlsDataPtr async_wait_result;
  GetUrls(&async_wait_result);
  return async_wait_result;
}

